private void enlarge(int size) {
    // Calculate the new capacity based on the current size and the requested size.
    int newCapacity = (int) Math.max(size, (long) (data.length * 1.75f));

    // Create a new byte array of the calculated capacity.
    byte[] newData = new byte[newCapacity];

    // Copy the contents of the current byte array to the new array.
    System.arraycopy(data, 0, newData, 0, data.length);

    // Initialize the remaining portion of the new array with zeros.
    Arrays.fill(newData, data.length, newData.length, (byte) 0);

    // Update the data reference to point to the new array.
    data = newData;
}

