public ByteVector putByteArray(byte[] byteArrayValue, int byteOffset, int byteLength) {
    // Check if the array is null and if the length is valid
    if (byteArrayValue == null || byteLength < 0) {
        throw new IllegalArgumentException("Invalid byte array or length");
    }

    // Calculate the new length of the byte vector
    int newLength = this.length + byteLength;

    // Enlarge the byte vector if necessary
    if (newLength > this.data.length) {
        byte[] newData = new byte[newLength];
        System.arraycopy(this.data, 0, newData, 0, this.length);
        this.data = newData;
    }

    // Copy the bytes of the array into the byte vector
    System.arraycopy(byteArrayValue, byteOffset, this.data, this.length, byteLength);

    // Update the length of the byte vector
    this.length = newLength;

    // Return the byte vector
    return this;
}

