private void pop(final String descriptor) {
    // Loop through the number of argument types specified in the descriptor
    for (int i = 0; i < descriptor.length(); i++) {
        // Pop the top string off the output frame stack
        final String argument = popString();

        // Check if the argument type was a primitive type
        if (PRIMITIVE_TYPES.contains(argument)) {
            // Pop the top object off the output frame stack
            final Object object = popObject();

            // Validate that the object matches the primitive type
            if (object != null && !argument.equals(object.getClass().getName())) {
                throw new IllegalStateException("Expected a " + argument + " but received a " + object.getClass().getName());
            }
        }
    }
}

