        System.out.println("Dist path " + DIST_PATH + " does not exist. Please ensure that the correct path is set in the application configuration.");
        return;
    }

    // Check if the config file exists
    File configFile = new File(DIST_PATH + "/config.cfg");
    if (!configFile.exists()) {
        System.out.println("Config file " + configFile.getAbsolutePath() + " does not exist. Please ensure that the correct path is set in the application configuration.");
        return;
    }

    // Load the config file
    Properties config = new Properties();
    try (FileInputStream fileInputStream = new FileInputStream(configFile)) {
        config.load(fileInputStream);
    } catch (IOException e) {
        System.out.println("Failed to load config file: " + e.getMessage());
        return;
    }

    // Set the dist path and configuration
    DIST_PATH = config.getProperty("dist.path");
    CONFIG = config;

